/**
 * Parsed command-line arguments for the coin change utility.
 */
public record CoinChangeArgs(int sum, int[] coins) {

    public CoinChangeArgs {
        coins = coins.clone();
    }

    @Override
    public int[] coins() {
        return coins.clone();
    }

    public static CoinChangeArgs parse(String[] args) {
        if (args.length < 1) {
            throw new IllegalArgumentException("expected at least a sum");
        }

        int sum = parseNonNegativeInt(args[0], "sum");
        int[] coins = new int[args.length - 1];
        for (int i = 1; i < args.length; i++) {
            coins[i - 1] = parsePositiveInt(args[i], "coin");
        }

        return new CoinChangeArgs(sum, CoinChangeDenominations.normalize(coins));
    }

    private static int parseNonNegativeInt(String value, String label) {
        try {
            int parsed = Integer.parseInt(value);
            if (parsed < 0) {
                throw new IllegalArgumentException(label + " must be non-negative");
            }
            return parsed;
        } catch (NumberFormatException ex) {
            throw new IllegalArgumentException("invalid " + label + ": " + value, ex);
        }
    }

    private static int parsePositiveInt(String value, String label) {
        int parsed = parseNonNegativeInt(value, label);
        if (parsed == 0) {
            throw new IllegalArgumentException(label + " values must be positive");
        }
        return parsed;
    }
}

public final class CoinChangeTest {

    private CoinChangeTest() {
        // Test utility.
    }

    public static void main(String[] args) {
        assertCount(5, new int[] {1, 2, 3}, 5);
        assertCount(1, new int[] {1, 2, 3}, 0);
        assertCount(5, new int[] {2, 5, 3, 6}, 10);
        assertCount(2, new int[] {1, 1, 2}, 3);
        assertCount(1, new int[] {2, 2}, 4);
        assertCountLong(5L, new int[] {1, 2, 3}, 5);
        assertCountWaysLong(5L, 5, 1, 2, 3);
        assertInputUnchanged();
        assertCount(1, new int[] {}, 0);
        assertCount(0, new int[] {}, 5);
        assertParsedArgs(5, new int[] {1, 2, 3}, new String[] {"5", "1", "2", "3"});
        assertParsedArgs(0, new int[] {}, new String[] {"0"});
        assertThrows(() -> CoinChange.count(null, 5));
        assertThrows(() -> CoinChange.count(new int[] {1, 0}, 5));
        assertThrows(() -> CoinChange.count(new int[] {1, 2}, -1));
        assertThrows(() -> CoinChangeArgs.parse(new String[] {}));
        assertThrows(() -> CoinChangeArgs.parse(new String[] {"-1"}));

        System.out.println("All CoinChange tests passed.");
    }

    private static void assertCount(int expected, int[] coins, int sum) {
        int actual = CoinChange.count(coins, sum);
        if (actual != expected) {
            throw new AssertionError(
                "expected " + expected + " ways for sum " + sum + ", got " + actual
            );
        }
    }

    private static void assertCountLong(long expected, int[] coins, int sum) {
        long actual = CoinChange.countLong(coins, sum);
        if (actual != expected) {
            throw new AssertionError(
                "expected " + expected + " ways for sum " + sum + ", got " + actual
            );
        }
    }

    private static void assertCountWaysLong(long expected, int sum, int... coins) {
        long actual = CoinChange.countWaysLong(sum, coins);
        if (actual != expected) {
            throw new AssertionError(
                "expected " + expected + " ways for sum " + sum + ", got " + actual
            );
        }
    }

    private static void assertInputUnchanged() {
        int[] coins = {3, 1, 2, 1};
        int[] original = coins.clone();
        CoinChange.count(coins, 5);
        if (coins.length != original.length) {
            throw new AssertionError("count should not change the input length");
        }
        for (int i = 0; i < coins.length; i++) {
            if (coins[i] != original[i]) {
                throw new AssertionError("count should not mutate the input array");
            }
        }
    }

    private static void assertParsedArgs(int expectedSum, int[] expectedCoins, String[] args) {
        CoinChangeArgs parsed = CoinChangeArgs.parse(args);
        if (parsed.sum() != expectedSum) {
            throw new AssertionError(
                "expected sum " + expectedSum + ", got " + parsed.sum()
            );
        }

        int[] parsedCoins = parsed.coins();
        if (parsedCoins.length != expectedCoins.length) {
            throw new AssertionError(
                "expected " + expectedCoins.length + " coins, got " + parsedCoins.length
            );
        }
        for (int i = 0; i < expectedCoins.length; i++) {
            if (parsedCoins[i] != expectedCoins[i]) {
                throw new AssertionError(
                    "expected coin " + expectedCoins[i] + " at index " + i + ", got " + parsedCoins[i]
                );
            }
        }

        if (parsedCoins.length > 0) {
            parsedCoins[0] = -1;
            int[] copiedCoins = parsed.coins();
            if (copiedCoins[0] == -1) {
                throw new AssertionError("coins() should return a defensive copy");
            }
        }
    }

    private static void assertThrows(Runnable action) {
        try {
            action.run();
        } catch (IllegalArgumentException expected) {
            return;
        }

        throw new AssertionError("expected IllegalArgumentException");
    }
}

import java.util.Arrays;

final class CoinChangeDenominations {

    private CoinChangeDenominations() {
        // Utility class.
    }

    static int[] normalize(int[] coins) {
        if (coins == null) {
            throw new IllegalArgumentException("coins must not be null");
        }
        if (coins.length == 0) {
            return coins;
        }

        int[] normalized = coins.clone();
        Arrays.sort(normalized);

        int uniqueCount = 0;
        int previous = 0;
        for (int coin : normalized) {
            if (coin <= 0) {
                throw new IllegalArgumentException("coin values must be positive");
            }
            if (uniqueCount == 0 || coin != previous) {
                normalized[uniqueCount++] = coin;
                previous = coin;
            }
        }

        return Arrays.copyOf(normalized, uniqueCount);
    }
}

/**
 * Utility for counting the number of ways to make a target sum with unlimited copies of each coin.
 */
public final class CoinChange {

    private CoinChange() {
        // Utility class.
    }

    /**
     * Counts the number of unique combinations that sum to {@code sum}.
     * Duplicate coin denominations are ignored.
     */
    public static int count(int[] coins, int sum) {
        return Math.toIntExact(countLong(coins, sum));
    }

    /**
     * Returns the exact number of unique combinations that sum to {@code sum}.
     * Duplicate coin denominations are ignored.
     */
    public static long countLong(int[] coins, int sum) {
        validateSum(sum);
        int[] normalizedCoins = CoinChangeDenominations.normalize(coins);
        return countCombinations(normalizedCoins, sum);
    }

    /**
     * Convenience overload for callers that already have coins as varargs.
     */
    public static int countWays(int sum, int... coins) {
        return count(coins, sum);
    }

    /**
     * Convenience overload that returns the exact combination count as a long.
     */
    public static long countWaysLong(int sum, int... coins) {
        return countLong(coins, sum);
    }

    public static void main(String[] args) {
        CoinChangeCli.main(args);
    }

    private static void validateSum(int sum) {
        if (sum < 0) {
            throw new IllegalArgumentException("sum must be non-negative");
        }
    }

    private static long countCombinations(int[] coins, int sum) {
        long[] ways = new long[sum + 1];
        ways[0] = 1L;

        for (int coin : coins) {
            for (int current = coin; current <= sum; current++) {
                ways[current] += ways[current - coin];
            }
        }

        return ways[sum];
    }
}

/**
 * Command-line entry point for the coin change utility.
 */
public final class CoinChangeCli {

    private CoinChangeCli() {
        // Utility class.
    }

    public static void main(String[] args) {
        try {
            run(args);
        } catch (IllegalArgumentException ex) {
            System.err.println(ex.getMessage());
            printUsage();
            System.exit(1);
        }
    }

    private static void run(String[] args) {
        CoinChangeArgs parsedArgs = CoinChangeArgs.parse(args);
        System.out.println(CoinChange.countWaysLong(parsedArgs.sum(), parsedArgs.coins()));
    }

    private static void printUsage() {
        System.err.println("Usage: java CoinChange <sum> [coin1 coin2 ...]");
        System.err.println("Example: java CoinChange 5 1 2 3");
        System.err.println("Example: java CoinChange 0");
    }
}
